WITH page_warehouse_agg AS ( SELECT cr.cr_catalog_page_sk, cr.cr_warehouse_sk, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_quantity) AS total_return_quantity, AVG(cr.cr_net_loss) AS avg_net_loss FROM catalog_returns cr GROUP BY cr.cr_catalog_page_sk, cr.cr_warehouse_sk ) SELECT cp.cp_department, cp.cp_catalog_number, cp.cp_type, cp.cp_catalog_page_number, w.w_warehouse_name, w.w_state AS warehouse_state, pw.total_net_loss, pw.total_return_quantity, pw.avg_net_loss, CASE WHEN pw.total_net_loss > 100000 THEN 'HIGH' WHEN pw.total_net_loss BETWEEN 50000 AND 100000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category, RANK() OVER (ORDER BY pw.total_net_loss DESC) AS net_loss_rank FROM page_warehouse_agg pw JOIN catalog_page cp ON pw.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN warehouse w ON pw.cr_warehouse_sk = w.w_warehouse_sk ORDER BY net_loss_rank LIMIT 10
